class Validators {static String? required(String? v)=>v==null||v.trim().isEmpty?'Campo obrigatório':null;static String? positive(String? v)=>double.tryParse(v?.replaceAll(',','.')??'')==null||double.parse(v!.replaceAll(',','.'))<=0?'Informe valor positivo':null;static String? nonnegative(String? v)=>double.tryParse(v?.replaceAll(',','.')??'')==null||double.parse(v!.replaceAll(',','.'))<0?'Informe um número válido':null;}
